#!/usr/bin/env bash
# Round 375 claims (L29 + L56). Run from the loop root: bash b-round-374/claims-375.sh
# STORE=<tree> runs the same commands on another tree. B's sketch output (claims-375-sketch-output.txt) came from
# STORE=b-round-374/scratch (cp -a of store/ at ad13a96 + sketch.patch.txt), removed after planning; recreate it with
# patch -p1 < b-round-374/sketch.patch.txt on a cp -a of store/ at ad13a96.
S=${STORE:-/home/runner/czaba-project/store}
B=b-round-374
L=$S/app/components/arrangement/ArrangementLibrary.tsx
P=$S/app/components/arrangement/ArrangementLibraryPreview.tsx
W=$S/app/components/arrangement/StudioWorkspace.tsx
C=$S/app/contexts/ArrangementContext.tsx
T=$S/app/lib/arrangement/__tests__
echo "K1 gate374: $(python3 -I -c "import json;d=json.load(open('gates/gate-round-374.json'));print(d['status'],d['commit'][:7])")"
echo "K2 status-lines: $(git -C $S status --short --untracked-files=all 2>/dev/null | grep -v node_modules | wc -l)"
echo "K3 Library: destructured wrapper 'export function ArrangementLibrary({' $(grep -c '^export function ArrangementLibrary({$' $L) props wrapper $(grep -c '^export function ArrangementLibrary(props: ArrangementLibraryProps) {$' $L) useArrangement() calls $(grep -c 'useArrangement()' $L) memo view $(grep -c '^export const ArrangementLibraryView = memo(ArrangementLibraryViewInner, sameLibraryLeafProps);$' $L)"
echo "K4 Preview: useArrangement() $(grep -c 'useArrangement()' $P) useArrangementActiveTrackId() $(grep -c 'useArrangementActiveTrackId()' $P) 'arrangement.tracks.find(' $(grep -c 'arrangement.tracks.find(' $P) 'activeTrack?.kind|activeTrack.name|activeTrack ?' reads $(grep -cE 'activeTrack(\?)?\.(kind|name)' $P) other activeTrack fields $(grep -oE 'activeTrack(\?)?\.[a-zA-Z]+' $P | grep -vcE '\.(kind|name)$') memo view $(grep -c '^export const ArrangementLibraryPreviewView = memo($' $P)"
echo "K5 StudioWorkspace Library site: '<ArrangementLibrary\$' $(grep -c '<ArrangementLibrary$' $W) '<ArrangementLibraryView\$' $(grep -c '<ArrangementLibraryView$' $W) useArrangementLibraryActions $(grep -c 'useArrangementLibraryActions(workspace)' $W)"
echo "K6 Master site (unchanged by this round): '<ArrangementMasterView master={arrangement.master} actions={masterActions} />' $(grep -c '<ArrangementMasterView master={arrangement.master} actions={masterActions} />' $W)"
echo "K7 name-keyed counts: drag-preview rendersOf('ArrangementLibrary') $(grep -c "rendersOf('ArrangementLibrary')" $T/drag-preview-render.test.tsx) rendersOf('ArrangementLibraryViewInner') $(grep -c "rendersOf('ArrangementLibraryViewInner')" $T/drag-preview-render.test.tsx) render-budget 'ArrangementLibrary' $(grep -c "'ArrangementLibrary'" $T/render-budget.test.tsx) library-preview get('ArrangementLibraryPreview') $(grep -c "get('ArrangementLibraryPreview')" $T/library-preview.test.tsx)"
echo "K8 SWEEP tests mounting the leaves (app/**/*.test.tsx): '<ArrangementLibrary' files $(grep -rlE '<ArrangementLibrary( |$)' $S/app --include=*.test.tsx | wc -l) '<ArrangementLibraryPreview' files $(grep -rlE '<ArrangementLibraryPreview( |$)' $S/app --include=*.test.tsx | wc -l)"
echo "K9 row ids: RB-LEAF3 $(grep -c "'RB-LEAF3 " $T/render-budget.test.tsx) LP-EQ1 $(grep -c "'LP-EQ1 " $T/library-preview.test.tsx) LP-EQ2 $(grep -c "'LP-EQ2 " $T/library-preview.test.tsx) RB-LEAF1 ArrangementMaster-0 $(grep -c "get('ArrangementMaster') ?? 0).toBe(0)" $T/render-budget.test.tsx)"
echo "K10 stable actions: useCallback decls $(grep -cE '^  const (selectSource|addSourceToActiveTrack|startLibraryPreview|stopLibraryPreview|getLibraryPreviewOffset|beginLibraryDrag|endLibraryDrag) = useCallback\(' $C) of 7; changeLibraryCollapsed $(grep -c 'const changeLibraryCollapsed = useCallback((collapsed: boolean) => {' $W)"
echo "K11 protected: $(cd $S && sha256sum -c --quiet /home/runner/czaba-project/tmp/studio-real-loop/b-round-318/protected-sha256.txt 2>&1 | wc -l) failing lines"
echo "K12 frozen: $(cd $S && sha256sum -c --quiet /home/runner/czaba-project/tmp/studio-real-loop/$B/r375-frozen-sha256.txt 2>&1 | wc -l) failing lines, entries $(wc -l < $B/r375-frozen-sha256.txt)"
echo "K13 sketch files sha: $(cd $S && sha256sum -c --quiet /home/runner/czaba-project/tmp/studio-real-loop/$B/sketch-files-sha256.txt 2>/dev/null | wc -l) failing lines (0 = the 6 files equal B sketch)"
