echo "K16 sketch typecheck/biome: $(tail -1 $B/sketch-typecheck.log) / $(tail -1 $B/sketch-biome.log)"
echo "K17 perf on sketch v2 (all specs): $(sed 's/\x1b\[[0-9;]*m//g' $B/perf-sketch.log | grep -E '^ +[0-9]+ (passed|failed)' | tr -s ' ' | tr '\n' ';') $(grep -E '^interact.zoom.1.components-per-key |^interact.zoom.30.components-per-key |^interact.play.start-components |^interact.click.components ' $B/perf-sketch-vs-head.txt | cut -d' ' -f1-3 | tr '\n' ';')"
echo "K18 patch sha: $(sha256sum $B/sketch.patch.txt | cut -c1-16) dispatched: $(cut -c1-16 $B/sketch-dispatched.sha256)"
echo "K19 mutants failed-test counts: $(for m in MU-LIB-NO-MEMO MU-PREVIEW-NO-MEMO MU-LEAF-PROPS-DEFAULT-EQUALITY MU-LIB-ACTIONS-FRESH MU-TRACK-LABEL-NO-NAME MU-TRACK-LABEL-NO-ID MU-LEAF-PROPS-NO-EXTRA-KEY MU-LIB-SITE-REVERT MU-PREVIEW-SITE-REVERT MU-MASTER-SITE-REVERT; do printf '%s=%s ' $m "$(sed 's/\x1b\[[0-9;]*m//g' $B/mutants/mutant-$m.log 2>/dev/null | grep -oE 'Tests +[0-9]+ failed' | grep -oE '[0-9]+' | head -1)"; done)"
echo "K20 expect/it counts: $(tr '\n' ';' < $B/expect-counts-375.txt)"
echo "K21 regression-last: $(python3 -I -c "import json;print(json.load(open('regression-last.json'))['date'])") lessons lines: $(wc -l < lessons.md)"
echo "K22 tasks/round-374.md sha256: $(sha256sum tasks/round-374.md | cut -c1-16)"
echo "K23 covering files: $(wc -l < $B/covering-375.txt)"
echo "K24 HEAD probe (dev): $(python3 -I -c "import json;d=json.load(open('$B/probe/leaf-head-375.json'));print(';'.join(vp+' '+st+' Lib '+str(d[vp]['steps'][st]['ArrangementLibrary'])+' Prev '+str(d[vp]['steps'][st]['ArrangementLibraryPreview']) for vp in ('1440x900','1280x720') for st in ('zoom-in-key','lane-mute-click','undo-ctrl-z')))")"
echo "K25 sketch probe (dev): $(python3 -I -c "import json;d=json.load(open('$B/probe/leaf-sketch-375.json'));print(';'.join(vp+' '+st+' LibView '+str(d[vp]['steps'][st]['ArrangementLibraryViewInner'])+' PrevView '+str(d[vp]['steps'][st]['ArrangementLibraryPreviewViewInner'])+' Lib '+str(d[vp]['steps'][st]['ArrangementLibrary']) for vp in ('1440x900','1280x720') for st in ('zoom-in-key','lane-mute-click','undo-ctrl-z','library-preview-start')))")"
echo "K27 strings/testids (HEAD-equal rows; not in the sketch output): listbox 'Sounds' $(grep -c "aria-label={studioLibraryPanelStrings.listLabel}\|aria-label=\"Sounds\"" $L) listLabel 'Sounds' $(grep -c "listLabel: 'Sounds'," $S/app/lib/arrangement/strings.ts) add 'Add' $(grep -c "^  add: 'Add',$" $S/app/lib/arrangement/strings.ts) addNeedsAudioTrackTitle $(grep -c "addNeedsAudioTrackTitle: 'Add — make an audio track active first'," $S/app/lib/arrangement/strings.ts) activeTrackLabel $(grep -c 'activeTrackLabel: (name: string): string => `${name} — set as the active track`,' $S/app/lib/arrangement/strings.ts) testid preview $(grep -c 'data-testid="arrangement-library-preview"' $P) testid search $(grep -c 'data-testid="arrangement-library-search"' $L) testid status $(grep -c 'data-testid="arrangement-status"' $W)"
echo "K28 HEAD recipe probe: $(python3 -I -c "import json;d=json.load(open('$B/probe/recipe-head-375.json'));print(';'.join(vp+' video '+str(d[vp]['afterVideoHeader']['addAriaDisabled'])+' music '+str(d[vp]['afterMusicHeader']['addAriaDisabled'])+' drag '+str(d[vp]['drag']['clipsBefore'])+'->'+str(d[vp]['drag']['clipsAfter']) for vp in ('1440x900','1280x720')))")"
